SELECT gen_random_uuid(), 'material', '488010dc-5779-4a00-b701-46f9dc7f4d3d', 1700, '面料仓', 100, 5000
WHERE NOT EXISTS (SELECT 1 FROM inventory WHERE type='material' AND material_id='488010dc-5779-4a00-b701-46f9dc7f4d3d' AND warehouse='面料仓');
UPDATE inventory SET quantity = quantity + 1700, created_at = now()
WHERE type='material' AND material_id='488010dc-5779-4a00-b701-46f9dc7f4d3d' AND warehouse='面料仓';


